(()=>{'use strict';
const dual=(z,e,tag='span',cls='')=>`<${tag} class="${cls}"><span class="zh" lang="zh-CN">${z}</span><span class="en" lang="en">${e}</span></${tag}>`;
const p=(z,e)=>dual(z,e,'p');
const S={campbell:'https://www.jcf.org/learn/joseph-campbell-heros-journey',conversations:'https://openlibrary.org/books/OL1890731M/The_hero%27s_journey',vogler:'https://chrisvogler.wordpress.com/2023/11/04/a-handy-handout/',voglerBook:'https://mwp.com/product/writers-journey-25th-anniversary-edition-mythic-structure-writers/',poetics:'https://classics.mit.edu/Aristotle/poetics.1.1.html',poetics2:'https://classics.mit.edu/Aristotle/poetics.2.2.html',field:'https://sydfield.com/guest-blog/utilizing-syd-fields-screenwriting-paradigm-to-understand-script-timeline-structureby-natalia-lazarus/',freytag:'https://briantriber.com/WritingSamples/Freytag_Drama/Freytag_11_Ch2_P2.html',kiel:'https://filmlexikon.uni-kiel.de/doku.php/p:pyramidenschema-3570',harmon:'https://web.archive.org/web/20050318084222/http://www.channel101.com:80/tutorials/tutorial.php?tutorial_id=11',wired:'https://www.wired.com/2011/09/mf-harmon/',american:'https://www.eerdmans.com/9780802825735/the-myth-of-the-american-superhero/',murdock:'https://maureenmurdock.com/articles-the-heroines-journey/',faces:'https://www.criterion.com/films/915-faces',facesBFI:'https://www.bfi.org.uk/features/john-cassavetes-faces-indie-filmmaking',pretty:'https://catalog.afi.com/Catalog/MovieDetailsPrintView/55709',paint:'https://www.academyfilms.com/portfolio/sony-paint',paintYear:'https://adage.com/article/the-creativity-awards/2007-creativity-award-winner-sony-bravia-paint/119101/',balls:'https://www.luerzersarchive.com/sony-bravia-2005-balls/',zone:'https://filmsandfestivals.britishcouncil.org/projects/the-zone-of-interest',zoneCamera:'https://www.leitz-cine.com/interview/lukasz-zal-psc',jcfBook:'https://www.jcf.org/product-page/the-hero-s-journey-joseph-campbell-on-his-life-and-work-ebook'};
const evidence=keys=>`<div class="evidence source-strip"><span class="evidence-label">${dual('资料依据','Evidence')}</span><span class="evidence-links">${keys.map(k=>`<a href="${S[k]}" target="_blank" rel="noopener">${k} ↗</a>`).join(' ')}</span></div>`;
const bookStructureByPage={'index.html':'beats','hero-journey.html':'cycle','three-act.html':'three','freytag.html':'pyramid','modern-monomyth.html':'cycle'};
function art(kind=0,heading='',zh='',questionZh='',questionEn=''){
 const volume=document.body.dataset.volume,M=window.BookStructureModels;let type,model,focus=[],labels,title;const clean=s=>s.replace(/^\d+\s*[·.：:]?\s*/,'').trim().toLowerCase();const find=list=>list.findIndex(x=>clean(x[1])===clean(heading)||clean(x[0])===clean(zh));
 if(volume==='books'){const target=bookEntries[kind][0];type=bookStructureByPage[target];model=target==='hero-journey.html'?'campbell':target==='modern-monomyth.html'?'harmon':type==='beats'?'beats':type;if(model==='harmon')title=['现代单一神话：以哈蒙八步为一例','Modern monomyth: Harmon’s eight steps as one example'];}
 else if(volume==='hero'){type='cycle';model=kind?.model||'campbell';if(heading){const i=find(M[model]);if(i>=0)focus=[i];else if(heading==='Departure / separation')focus=[0,1,2,3,4];else if(heading==='Initiation')focus=[5,6,7,8,9,10];else if(heading==='Return')focus=[11,12,13,14,15,16];else return '';}}
 else if(volume==='modern'){type='cycle';model='harmon';if(heading){if(heading.startsWith('Vogler'))model='vogler';else if(heading.startsWith('Maureen Murdock')){model='murdock';labels=[['离开女性价值','Separation from the feminine'],['认同男性价值','Identification with the masculine'],['试炼','Trials'],['成功的幻觉','Illusory success'],['精神枯竭','Spiritual aridity'],['下潜与启蒙','Descent and initiation'],['渴望重连女性价值','Longing to reconnect with the feminine'],['修复母女分裂','Heal mother/daughter split'],['修复受伤的男性面向','Heal the wounded masculine'],['整合','Integration']];title=['默多克 · 女英雄之旅','Murdock · The Heroine’s Journey'];focus=[3,4,5,7,9];}else{const i=find(M.harmon);if(i<0)return '';focus=[i];}}}
 else if(volume==='three'){model='three';type='three';if(heading==='Beginning, middle, end'){type='flow';model='aristotle';labels=[['开端：行动的起因','Beginning: causal start'],['中间：承前启后','Middle: follows and leads'],['结尾：完成后果','End: completes consequences']];title=['亚里士多德：行动完整性，不是幕间页码','Aristotle: causal completeness, not act-page targets'];}else if(/^Act I ·/.test(heading))focus=[0];else if(/^Act II ·/.test(heading))focus=[1];else if(/^Act III ·/.test(heading))focus=[2];else return '';}
 else if(volume==='freytag'){model='pyramid';type='pyramid';const i=find(M.pyramid);if(i<0)return '';focus=[i];}else return '';
 const plain=s=>{const el=document.createElement('span');el.innerHTML=s;return el.textContent.replace(/\s*→\s*$/,'').trim();};
 return window.BookStructureArt(type,{model,focus,labels,title,heading:heading?[plain(zh),plain(heading)]:undefined,caption:questionZh?[questionZh,questionEn]:undefined});}
function row(z,e,bz,be,qz,qe,i=0){const visual=art(i,e,z,qz,qe);return `<article class="editorial-row library-row${visual?'':' text-only-row'}">${visual?`<figure class="concept-visual">${visual}</figure>`:''}<div class="row-copy">${dual(z,e,'h3')}${p(bz,be)}${dual(qz,qe,'p','composition-question')}</div></article>`}

const note=(z,e,bz,be)=>`<aside class="callout">${dual(z,e,'h3')}${p(bz,be)}</aside>`;
const checklist=items=>`<section class="workshop">${dual('导演的工作清单','A director’s checklist','h3')}<ul class="director-checklist">${items.map(x=>`<li>${dual(x[0],x[1])}</li>`).join('')}</ul></section>`;
const section=(id,z,e,body)=>`<section class="cine-section" id="${id}">${dual(z,e,'h2')}${body}</section>`;
const intro=(z,e,bz,be)=>`<section class="cine-intro">${dual(z,e,'h1')}${dual(bz,be,'p','lede')}${p('本页区分已核对的书目与概念、课程自己的电影解读，以及供你试拍的问题。电影例子含剧透；对应关系不是创作者使用某套公式的证明。','This page separates verified bibliography and concepts, our own film readings, and questions for your tests. Film examples contain spoilers; a mapping does not prove the filmmakers used a formula.')}</section>`;
const refs=keys=>section('reading-sources','来源与阅读边界','Sources & reading boundaries',p('以下是本次查阅的公开资料。内容为独立中英释义，不是整本书的翻译。古典术语与中文书名存在不同译法，英文名称用来稳定对照。','Public sources consulted for this page are below. The content is independently paraphrased in Chinese and English, not a translation of an entire book. Classical terms and Chinese book titles vary between translations; English names anchor the comparison.')+evidence(keys)+`<a href="./books.html#comparison">${dual('横向比较所有结构 →','Compare the structures →')}</a>`);
function quiz(z,e,options,answer,rz,re){return `<section class="quiz library-quiz" data-correct="${answer}"><div class="quiz-head">${dual('读完，自问一次','A short self-check')}</div>${dual(z,e,'h4')}<div class="quiz-options">${options.map((x,i)=>`<button class="quiz-option" type="button" data-answer="${i}" aria-pressed="false">${dual(x[0],x[1])}</button>`).join('')}</div><div class="quiz-feedback" aria-live="polite" data-zh="${rz}" data-en="${re}"></div></section>`}
const cStages=[
['冒险的召唤','The Call to Adventure','某种缺失、讯息或遭遇，把日常生活指向一个未知领域。','A lack, message, or encounter points beyond everyday life.','不回应这个变化，会失去什么？','What is lost by not responding?'],
['拒绝召唤','Refusal of the Call','恐惧、责任或依恋使人回避变化；这揭示出发的代价。','Fear, duty, or attachment makes change difficult and gives departure a cost.','拒绝是一个可见行动，还是只写在对白里？','Is refusal visible in behavior, or only stated?'],
['超自然援助','Supernatural Aid','神话中常有保护者或赠物；电影可以把它转化为帮助和经验。','Myth often provides a protector or gift; film can translate this into help or experience.','援助让人物能行动，还是替人物完成选择？','Does help enable a choice or make it for the character?'],
['跨越第一道门槛','The Crossing of the First Threshold','人物进入另一套规则，边界常由守卫、禁令或困难体现。','A boundary, guardian, or prohibition marks entry into unfamiliar rules.','跨过去后，哪条旧规则不再有效？','Which old rule stops working beyond the boundary?'],
['鲸腹','The Belly of the Whale','与熟悉世界分离，旧身份暂时失效；象征性进入转化过程。','Separation suspends an old identity: a symbolic entry into transformation.','能用空间与声音表现失去旧身份，而不照拍一条鲸吗？','Can space and sound convey this without a literal whale?'],
['试炼之路','The Road of Trials','连续考验改变能力与理解，不必是重复升级的打斗。','Trials alter capacity and understanding, not merely the size of a fight.','每次试炼改变了哪一项资源、关系或判断？','What resource, relationship, or judgment changes in each trial?'],
['与女神相遇','The Meeting with the Goddess','原著的神话象征涉及完整性与接纳，不等于必须安排爱情线。','Campbell’s mythic symbolism concerns wholeness and acceptance, not a compulsory romance.','“获得接纳”在这个人物的生活中具体是什么？','What would being accepted mean in this person’s life?'],
['女人作为诱惑者','Woman as the Temptress','这是原著带时代与性别偏向的称谓。实践上可检视任何让任务失焦的诱惑，不把女性等同障碍。','This historical label carries a gendered bias. In practice examine any diverting attachment; do not equate women with obstacles.','是谁在定义诱惑？有没有把一个人写成主角的工具？','Who defines temptation, and is another person reduced to a device?'],
['与父亲和解／合一','Atonement with the Father','面对支配性的权威、恐惧或价值来源；不要求字面上的父子重聚。','Confront a source of authority, fear, or value; a literal father–child reunion is not required.','人物是接受权威、重新理解它，还是拒绝它？','Does the character accept, reinterpret, or reject that authority?'],
['神化／顿悟','Apotheosis','神话中的升华或意识扩展，为理解世界提供新的位置。','A mythic elevation or expansion of consciousness changes the position from which the world is understood.','新的理解会改变哪一个下一步动作？','Which next action changes because of the insight?'],
['终极恩赐','The Ultimate Boon','获得旅程所追寻的事物或认识；外在奖赏未必是最终意义。','The sought object or knowledge is attained; an external prize may not be the deepest gain.','得到目标，与真正需要它，是同一回事吗？','Is getting the goal the same as needing it?'],
['拒绝返回','Refusal of the Return','人物可能留恋获得启示的领域，不愿回到普通生活。','The transformed realm may be so attractive that ordinary life is resisted.','为什么回去比留下更难？','Why might returning be harder than remaining?'],
['魔法逃亡','The Magic Flight','带走恩赐可能引发追逐；有些神话得到祝福，则返回更平顺。','Taking the boon can provoke pursuit; other stories allow a blessed, easier return.','带回所得，带来了什么新代价？','What new cost comes with bringing the gain back?'],
['外界救援','Rescue from Without','他人的帮助让人物能够完成归返，承认英雄不是自足的。','Outside assistance enables return and acknowledges that a hero is not self-sufficient.','谁的劳动和风险被“孤胆英雄”的叙述遮住了？','Whose work and risk are hidden by the lone-hero story?'],
['跨越返回的门槛','The Crossing of the Return Threshold','难题是把特殊经验带进日常，而不只是地理上到家。','The challenge is integrating extraordinary experience into ordinary life, not merely arriving home.','学到的东西如何进入一次普通的互动？','How does the learning enter an ordinary exchange?'],
['两个世界的主人','Master of the Two Worlds','能够在不同经验和价值之间往返，不必只认同一个身份。','The figure can move between modes of experience without being confined to one identity.','哪两种原本不相容的生活，现在能被并置？','Which formerly incompatible ways of living can now coexist?'],
['生活的自由','Freedom to Live','对死亡、损失和未来的关系改变；不是保证永久幸福。','The relation to mortality, loss, and the future changes; permanent happiness is not guaranteed.','最后一个动作如何表现与恐惧的新关系？','What final action shows a changed relation to fear?']];
const vStages=[
['平凡世界','Ordinary World','先建立人物的日常关系与不平衡。','Establish everyday relations and an existing imbalance.'],['冒险召唤','Call to Adventure','变化打断现状。','Change interrupts the existing situation.'],['拒绝召唤','Refusal of the Call','呈现未知带来的恐惧或阻力。','Make fear of the unknown or resistance visible.'],['遇见导师','Meeting with the Mentor','获得经验、工具或内在勇气。','Gain experience, tools, or courage from within.'],['跨越门槛','Crossing the First Threshold','投入新行动与新规则。','Commit to a new course and unfamiliar rules.'],['考验、盟友、敌人','Tests, Allies, Enemies','在行动中辨认关系、练习新能力。','Discover allegiances and practice new capacities in action.'],['接近最深洞穴','Approach to the Inmost Cave','为核心考验准备，压力集中。','Prepare for the central challenge as pressure gathers.'],['严峻考验','Ordeal','面对死亡或最深恐惧，旧自我遭到挑战。','Confront death or a deepest fear as the old self is challenged.'],['奖赏','Reward','获得成果，但仍可能再次失去。','A gain is made, but can still be lost.'],['归途','The Road Back','决定完成旅程，把成果带回。','Commit to completing the journey and bringing the gain back.'],['复活／最终考验','Resurrection','在更完整的最后考验中，以行动证明改变。','A more complete final test makes change visible through action.'],['携灵药归返','Return with the Elixir','改变不仅留在人物内心，也影响生活和他人。','Change reaches everyday life and others, not only the inner self.']];
function heroPage(){return intro('不是每个故事都要走遍十七站。','Not every story needs all seventeen stations.','从神话的比较研究，到银幕上的人物变化。','From comparative mythology to character change on screen.')+
section('which-book','先厘清是哪一本书','First, which book?',p('约瑟夫·坎贝尔（Joseph Campbell）的单一神话理论，主要以 1949 年《千面英雄》（The Hero with a Thousand Faces）为起点。The Hero’s Journey 也是一本 1990 年出版的谈话与生平材料集的书名，后来有不同版本；两者不是同一本书。','Campbell’s monomyth is principally associated with The Hero with a Thousand Faces (1949). The Hero’s Journey is also the title of a 1990 collection of conversations and biographical material, issued in later editions. These are not the same book.')+evidence(['campbell','conversations','jcfBook'])+note('描述性的模式，不是跨文化定律','A descriptive pattern, not a cross-cultural law','基金会特别提醒：离别／出发、启蒙／历险、归返是三大阶段；阶段内部的十七个常见母题是可变的，不要求全部出现或依序发生。坎贝尔的普遍性主张和性别框架也可以被质疑。','The Foundation distinguishes three phases—separation/departure, initiation, return—from variable motifs within them. The seventeen familiar motifs need not all appear or occur sequentially. Campbell’s universal claims and gender framework are open to criticism.'))+
section('phases','三大阶段','Three phases',`<div class="wide-diagram">${art(2)}</div>`+row('出发／离别','Departure / separation','离开旧秩序，或失去维持旧生活的条件。','Leave an old order, or lose the conditions that sustained it.','门槛在哪个可见动作上发生？','Which visible action crosses the threshold?',0)+row('启蒙／历险','Initiation','试炼、援助与获得新认识，改变人与世界的关系。','Trials, aid, and new understanding alter the relation to the world.','不是只变强，人物究竟变懂了什么？','Beyond becoming stronger, what is understood differently?',3)+row('归返','Return','把所得带回日常；获得意义与能分享意义是两件事。','Bring the gain into ordinary life; having meaning and sharing it are different tasks.','回到同一个地方，什么已经不同？','What differs on returning to the same place?',2))+
section('seventeen','十七个常见母题','Seventeen recurring motifs',p('分组：1–5 出发，6–11 启蒙，12–17 归返。以下为教学释义，不是每部影片必须完成的清单；保留英文原术语以便查阅。','Grouping: 1–5 departure, 6–11 initiation, 12–17 return. These are teaching paraphrases, not requirements for every film; English terms support further reading.')+cStages.map((x,i)=>row(String(i+1).padStart(2,'0')+' · '+x[0],x[1],...x.slice(2),i)).join(''))+
section('vogler','沃格勒的十二阶段银幕改写','Vogler’s twelve-stage screen adaptation',p('克里斯托弗·沃格勒（Christopher Vogler）的《作家之旅》把神话研究转为写作工具。十二阶段是他的实用改编，不能倒写成坎贝尔原著的十二步。其当前公开讲义把 Ordeal 放在故事中段附近，把 Resurrection 放在最终高潮：二者不是同一个节拍。','Christopher Vogler’s The Writer’s Journey turns myth scholarship into a writing tool. The twelve stages are his practical adaptation, not Campbell’s original twelve-step list. His public handout places the Ordeal near the middle and Resurrection at the final climax: they are different functions.')+evidence(['vogler','voglerBook'])+vStages.map((x,i)=>row(String(i+1).padStart(2,'0')+' · '+x[0],x[1],x[2],x[3],'这一站改变了哪个关系或决定？','Which relationship or decision changes here?',{model:'vogler',index:i})).join(''))+
section('examples','拉片：映射与留白','Film study: mappings and gaps',row('《星球大战》（1977）','Star Wars (1977)','基金会记录卢卡斯对坎贝尔影响的承认。教学上可观察：卢克离开塔图因、在新环境学习、在攻击死星时选择信任。不要为了凑齐十七项而编造不存在的桥段。','The Foundation documents Lucas acknowledging Campbell’s influence. For study, observe Luke leaving Tatooine, learning in an unfamiliar world, and choosing trust in the Death Star attack. Do not invent scenes to fill seventeen boxes.','哪个转变来自选择，而不是能力升级？','Which change comes from a choice, not a power upgrade?',0)+row('《绿野仙踪》（1939）','The Wizard of Oz (1939)','沃格勒用堪萨斯与奥兹的差异说明日常／特殊世界。把“回家”的愿望，与多萝西在旅途中建立的关系一起看。这里是功能阅读，不声称电影按该书创作。','Vogler uses the contrast between Kansas and Oz to explain ordinary and special worlds. Read Dorothy’s desire for home alongside the relationships developed on the journey. This is functional analysis, not a claim that the film used his later book.','两个世界的色彩、声音和表演节奏如何不同？','How do color, sound, and performance rhythm distinguish the worlds?',2)+`<a href="./films.html#pretty-woman">${dual('再比较《风月俏佳人》的门槛与主体性 →','Compare thresholds and agency in Pretty Woman →')}</a>`)+checklist([['用三句话写离开、被改变、如何带回；再决定是否需要细分。','Write departure, transformation, and return in three sentences before adding stages.'],['把门槛做成调度、声音或空间条件的变化，不只是换背景。','Make the threshold a change in blocking, sound, or spatial conditions, not only scenery.'],['标出不适用的阶段，并说明为什么；删去比硬套更有价值。','Mark inapplicable stages and explain why; omission is better than force-fitting.'],['检查谁拥有行动权，谁只被用来帮助英雄。','Check who has agency and who exists only to assist the hero.']])+quiz('沃格勒的 Ordeal 与 Resurrection 应怎样理解？','How should Ordeal and Resurrection be distinguished?',[['都是固定在最后一分钟的同一件事。','They are one event fixed to the last minute.'],['前者常是中段考验，后者是最终转化的考验；不是强制时码。','The former is often a middle ordeal, the latter a final transformational test; neither is a compulsory timestamp.']],1,'阶段有不同功能，且不要求每个故事都填满。','The stages serve different functions, and not every story needs every one.')+refs(['campbell','conversations','vogler','voglerBook']);}
function threePage(){const concepts=[
['开端、中间、结尾','Beginning, middle, end','亚里士多德讨论一个完整行动的因果形态：开端不必由前事必然引起，中间承前启后，结尾完成其后果。不是规定三幕的页码。','Aristotle describes the causal shape of a complete action: a beginning need not necessarily follow an earlier event, a middle follows and leads onward, and an end completes the consequences. This does not prescribe three screenplay acts.','删掉这一场，会破坏因果还是仅缩短时长？','Would removing this scene break causality or merely shorten duration?'],
['行动的统一','Unity of action','统一不是“同一个英雄经历的一切”。选择彼此相依的行动，使移走一部分会改变整体；也不等于电影必须遵守时空一致。','Unity is not everything that happens to one hero. Select interdependent actions so removing a part changes the whole; this is not a requirement for cinematic unity of time and place.','支线是在改变主要行动，还是只有共同人物？','Does the subplot alter the main action, or merely share a character?'],
['突转／逆转','Peripeteia','行动依照可能或必然的关系，转向预期的反面；不是随机加入惊吓。','An action reverses toward its opposite through probability or necessity, rather than an arbitrary surprise.','坏结果能从人物原本以为正确的动作中长出来吗？','Can the bad result grow from an action believed to be right?'],
['发现／认知','Anagnorisis','从不知到知，改变人物间的关系及命运；《俄狄浦斯王》是《诗学》讨论的典型，不是现代电影公式的原稿。','A movement from ignorance to knowledge changes relations and fortune. Oedipus is a central example in Poetics, not a draft of a modern film formula.','知道真相之前和之后，同一句话为什么会不同？','Why would the same line differ before and after recognition?'],
['净化／宣泄','Catharsis','悲剧与怜悯、恐惧及其净化的关系，是长期有争论的理论问题。不要把它缩减成“必须催泪”或唯一正确的心理疗效。','The relation between tragedy, pity, fear, and catharsis remains debated. Do not reduce it to compulsory tears or one definitive therapeutic effect.','观众最后如何重新理解此前的恐惧？','How does the audience understand an earlier fear differently at the end?'],
['过失／判断错误','Hamartia','可以理解为造成转折的错误或失误；“悲剧性缺陷”是常见后世解读，但不总等于天生邪恶或道德污点。','An error or mistake can bring about the turn. “Tragic flaw” is a familiar later reading, but is not always innate wickedness or a moral defect.','人物做错了什么，与人物是坏人，是一回事吗？','Is making an error the same as being a bad person?']];
return intro('因果完整，不等于三幕页码。','Causal completeness is not an act-page formula.','把《诗学》的问题，与现代编剧的工作模型分开。','Separate the questions of Poetics from modern screenplay working models.')+
section('aristotle','亚里士多德到底说了什么？','What did Aristotle actually say?',p('《诗学》（Poetics）分析悲剧、史诗及其构成。它强调行动、情节与整体性，并未写出今天所谓“第一幕 25%、第二幕 50%、第三幕 25%”的电影规则。把古典讨论直接冠名“三幕结构 by Aristotle”，会让后来的实践看起来像原文规定。','Poetics analyzes tragedy, epic, and their construction. It emphasizes action, plot, and wholeness; it does not prescribe the modern 25% / 50% / 25% screenplay formula. Labeling today’s three-act structure simply “by Aristotle” mistakes later practice for an ancient instruction.')+concepts.map((x,i)=>row(...x,i)).join('')+evidence(['poetics','poetics2']))+
section('modern-acts','现代三幕：一个实用模型','Modern three acts: a practical model',p('悉德·菲尔德的《电影剧本写作基础》（Screenplay，1979）推广了 Setup / Confrontation / Resolution 的范式和幕间情节点。它与古典因果思想可对读，但不是《诗学》的直接复刻，也不能说菲尔德发明了所有三幕叙事。','Syd Field’s Screenplay (1979) popularized a Setup / Confrontation / Resolution paradigm with act-boundary plot points. It can be read alongside classical causality, but is not a direct transcription of Poetics, nor did Field invent every three-part narrative.')+row('第一幕 · 建立','Act I · setup','建立人物、关系、世界与戏剧方向。第一情节点把行动推向新的持续冲突。','Establish people, relationships, world, and dramatic direction. Plot Point I turns the action toward a sustained new conflict.','这不是“人物简介”，而是谁必须作出什么选择？','Beyond a character introduction, who must choose what?',0)+row('第二幕 · 对抗','Act II · confrontation','人物试图解决问题，遭遇阻力；第二情节点使故事转向解决。不是把中间写长就完成了这一幕。','Attempts to solve the problem meet resistance; Plot Point II turns the action toward resolution. A long middle alone does not perform this function.','每次努力，是否让下一次选择更难或更不同？','Does each attempt make the next choice harder or different?',3)+row('第三幕 · 解决','Act III · resolution','核心行动产生结果；解决不保证快乐，也不等于必须解释一切。','The central action reaches consequences. Resolution need not be happy or explain everything.','结尾解决了最初的因果问题，还是另开了一个故事？','Does the ending resolve the initial causal problem, or begin a different story?',1)+note('比例是诊断工具','Proportions are diagnostic','菲尔德的常见示意以约 120 页为背景，约 30 / 60 / 30 页分配三幕；实际边界可移动。这里不把这一示意与救猫咪的 110 页位置混为统一标准。短片更不需要按页数等比填空。','A familiar Field illustration uses roughly 120 pages, with about 30 / 60 / 30 across the acts; boundaries can move. This is not the same page model as Save the Cat’s 110-page illustration. Shorts do not need proportionally filled page boxes.')+evidence(['field']))+
section('act-study','拉片：一个决定如何产生后果','Film study: how a decision produces consequences',row('《风月俏佳人》（1990）','Pretty Woman (1990)','课程解读：交易建立共同空间；相处让双方原有的价值观产生摩擦；薇薇安拒绝被安排成长期包养关系，迫使爱德华作出不同于交易的行动。分幕是阅读方法，不是已核实的原作者工作过程。','Our reading: a transaction establishes shared space; proximity exposes conflicting values; Vivian’s refusal of a kept arrangement forces Edward toward an action unlike a transaction. This act reading is a method of analysis, not a verified account of the writer’s process.','如果拿掉她的拒绝，最后的楼梯场面还意味着同样的东西吗？','Without her refusal, would the final fire-escape scene mean the same thing?',0)+evidence(['pretty'])+`<a href="./films.html#pretty-woman">${dual('看完整导演观察 →','Read the full director’s study →')}</a>`)+checklist([['给每个场景写“因为……所以……”，再检查是否只是“然后”。','Describe scenes with because / therefore, and notice mere and-then links.'],['区分信息揭晓、价值观改变与情节逆转，它们可以重合但不是同义词。','Distinguish information revealed, a value changed, and a reversal; they may coincide but are not synonyms.'],['对非线性电影，先写事件因果，再写观众的获知顺序。','For nonlinear films, map event causality separately from the audience’s order of discovery.'],['先找真正的问题与后果，再用页数检查节奏；不要反过来填空。','Find the question and consequences before checking page rhythm; do not reverse the process.']])+quiz('“亚里士多德规定电影必须有三个等比例的幕。”','“Aristotle prescribed three proportioned acts for cinema.”',[['正确，是《诗学》的原始规则。','True: it is an original rule in Poetics.'],['错误：完整行动的开中尾，与后来的三幕编剧模型应分开。','False: beginning–middle–end completeness should be distinguished from later screenplay models.']],1,'古典概念可以帮助分析因果，不能被改写成不存在的电影页码规定。','Classical concepts help analyze causality, but should not be rewritten as nonexistent screenplay page rules.')+refs(['poetics','poetics2','field','pretty']);}
function pyramid(){return `<figure class="pyramid-study">${window.BookStructureArt('pyramid')}${dual('数字对应下方五部分；顶点是居中的高潮，不表示固定分钟数。','Numbers match the five parts below; the peak is the central climax, not a fixed minute.','figcaption')}</figure>`}
function freytagPage(){const five=[['引介','Introduction','交代已存在的关系、冲突条件和世界，让后面的触发力有地方发生。','Establish relations, conditions of conflict, and a world in which an inciting force can act.','哪些信息必须先有，观众才理解触发事件？','What must be known to understand the inciting event?'],['上升','Rise','被触发的行动逐步发展与增强，人物的欲望转成实际后果。','An activated action develops and intensifies as desire produces consequences.','人物哪一次主动行动把自己推得更远？','Which deliberate action carries the character further?'],['高潮／顶点','Climax','原模型的中心转折组，常在全剧中部附近；它把上升转为反向行动，不是现代常说的片尾最大场面。','The original model’s central turning group, often near the middle, redirects the rising action into counteraction. It is not simply the biggest scene near a film’s end.','什么中心行动使其后的世界不能恢复原状？','Which central action makes restoration impossible?',],['下降／回落','Return / fall','反向力量与行动后果展开，不能理解为戏剧张力只能下降。','Counterforces and consequences unfold; this does not mean tension must only decrease.','此前的胜利如何变成新的危险？','How does an earlier victory become a danger?'],['灾变／结局','Catastrophe','悲剧行动完成其结果；现代改用时可以讨论结局，但不要把原模型的灾变自动改成幸福大团圆。','The tragic action reaches its outcome. Modern adaptations may discuss an ending more generally, but should not silently turn the original catastrophe into a happy resolution.','结局完成的是哪条已经启动的因果？','Which activated chain of causality does the ending complete?']];
return intro('金字塔的顶点，不在片尾。','The pyramid’s peak is not the final scene.','读原来的戏剧模型，再谨慎地转用到电影。','Read the original drama model before adapting it to film.')+
section('original-model','1863 年的模型','The 1863 model',p('古斯塔夫·弗赖塔格（Gustav Freytag）的《戏剧技巧》（Die Technik des Dramas，1863）分析戏剧行动，把它组织为五部分与三个转接时刻。它不是“五个长度相等的幕”或“每部电影都必须符合的山形曲线”。','Gustav Freytag’s Die Technik des Dramas (1863) analyzes dramatic action in five parts and three transitional moments. This does not mean five equal-length acts or a compulsory mountain-shaped graph for every film.')+pyramid()+five.map((x,i)=>row((i+1)+' · '+x[0],x[1],...x.slice(2),i)).join('')+evidence(['freytag','kiel']))+
section('three-crises','三个转接时刻／危机','Three transitional moments / crises',row('激发力','Exciting force / moment','在引介与上升之间，让潜在冲突开始成为行动。弗赖塔格认为这一发动环节是必要的。','Between introduction and rise, a latent conflict becomes action. Freytag treats this activating moment as necessary.','如果没有这个动作，后面的事仍会自己发生吗？','Would later events happen anyway without this action?',0)+row('悲剧力','Tragic force / moment','在中心高潮与回落之间，启动反作用。原文不把后两个时刻都当成每一出戏的硬性要求。','Between the central climax and fall, counteraction is activated. The original text does not require both later moments in every play.','什么把中心胜利转化为不可避免的代价？','What turns a central triumph into an unavoidable cost?',1)+row('最后悬念','Moment of last suspense','结局前短暂打开另一种可能，然后完成既定行动。不是随意再加一个反转。','Before the outcome, another possibility briefly opens, then the established action completes. This is not an arbitrary extra twist.','最后一点希望能从已经铺设的人物与条件中产生吗？','Can the last hope arise from established people and conditions?',3))+
section('film-transfers','怎样转用到电影？','How might this transfer to film?',row('《蜘蛛巢城》（1957）','Throne of Blood (1957)','黑泽明的莎士比亚《麦克白》改编可用于比较悲剧行动。课程观察：诱惑、夺权、反作用与毁灭可以连成因果；不要因此把电影的精确中点或分场冒充弗赖塔格本人的分析。','Kurosawa’s adaptation of Macbeth offers a comparison for tragic action. Our reading links temptation, seizure of power, counteraction, and destruction causally; it does not attribute the film’s precise midpoint or scene divisions to Freytag.','夺得目标的动作，怎样种下毁灭的条件？','How does attaining the goal create the conditions of destruction?',1)+`<p class="evidence"><a href="https://www.criterion.com/films/735-throne-of-blood" target="_blank" rel="noopener">Criterion · Throne of Blood ↗</a></p>`+row('《风月俏佳人》（1990）作为反例','Pretty Woman (1990) as a limit case','现代浪漫喜剧的结尾可以完成相互选择，而不是灾变。可比较关系变化，但没有必要把每一部喜剧都重新命名为悲剧金字塔。','A romantic comedy can end in reciprocal choice rather than catastrophe. Compare relational change, but do not rename every comedy a tragic pyramid.','这个模型在哪个地方开始无法解释影片？','At what point does the model stop explaining the film?',3)+p('原创练习：一名放映员隐瞒设备故障 → 擅自启动首映 → 成功却造成火灾隐患 → 隐瞒变成调查与追责 → 面对后果。试写一个中心行动造成反作用的短片；这不是来自任何已上映影片的情节。','Original exercise: a projectionist conceals a fault → runs a premiere without permission → succeeds but creates a fire risk → concealment brings investigation and accountability → consequences arrive. Write a short in which a central action creates counteraction. This is an invented exercise, not a synopsis of a released film.'))+checklist([['把图的中心写成具体行动，不要只标“最精彩”。','Name the central action, rather than labeling it most exciting.'],['分开“行动方向下降”与“张力降低”；后果可以越来越紧。','Separate falling action from falling tension; consequences can intensify.'],['检查电影是否真的需要灾变结局；不适用时明确写“不适用”。','Check whether the film needs catastrophe; explicitly mark non-applicability.'],['不要把救猫咪的 Midpoint、Finale 与本模型的 Climax 当成同义词。','Do not treat Save the Cat’s Midpoint or Finale as synonyms for this model’s Climax.']])+quiz('原来的弗赖塔格 Climax 最接近什么？','What best describes Freytag’s original Climax?',[['中心转折组，把上升推向反向行动。','A central turning group redirecting rise into counteraction.'],['每部电影最后五分钟的最大动作场面。','Every film’s biggest action scene in its final five minutes.']],0,'原模型的中心顶点与现代常说的片尾高潮要分开。','Distinguish the original central peak from the modern sense of a late climax.')+refs(['freytag','kiel']);}
function modernPage(){const circle=[['你／舒适区','You','建立一个人物或共同体暂时熟悉的秩序。','Establish an order temporarily familiar to a person or community.'],['需要','Need','出现缺失或愿望，给行动一个方向。','A lack or desire gives action a direction.'],['出发','Go','进入不熟悉的条件。','Enter unfamiliar conditions.'],['寻找／适应','Search','试错、适应与学习。','Try, adapt, and learn.'],['找到','Find','得到想要的事物，未必解决真实需要。','Get what was wanted, not necessarily what was needed.'],['付出代价','Take','成果带来代价或迫使人物面对失去。','A gain exacts a price or confronts the character with loss.'],['返回','Return','回到某种熟悉的秩序或重新面对起点。','Return to a familiar order or confront the starting condition again.'],['改变','Change','表现不同的关系、选择或理解。','Show a different relationship, choice, or understanding.']];
return intro('“现代单一神话”不是这里假定的一本书。','“Modern monomyth” is not treated as one identified book.','用一个明确命名的专题，比较改写、压缩与批评。','An explicitly defined topic comparing adaptation, compression, and critique.')+
section('interpretation','本页采用哪一种解释？','Which interpretation is used here?',note('解释选择 · 编辑说明','Interpretive choice · editorial note','书单只给出 Modern Monomyth，没有作者、版本或书名识别信息；我们不把它伪装成可唯一辨认的书。本页将其解释为“坎贝尔之后，现代银幕对单一神话的改写与批评”，以沃格勒为写作入口，加入哈蒙、劳伦斯／朱厄特和默多克的对照，因为这能同时回答如何使用、以及何时不该使用。','The list gives Modern Monomyth without an author, edition, or identifying title. We do not pretend it uniquely identifies a book. This page uses it as an umbrella for modern screen adaptations and critiques after Campbell: Vogler as the writing entry point, alongside Harmon, Lawrence/Jewett, and Murdock. This addresses both use and limits.')+p('以下四个框架既不是同一个理论的四种译名，也不是统一的升级路线。有的是写作工具，有的是文化批评，有的是经验与心理整合的模型。','These are not four translations of one theory, or a single ladder of progress. They include writing tools, cultural criticism, and a model of experience and psychological integration.'))+
section('frameworks','四个不同的问题','Four different questions',row('沃格勒 · 银幕改写','Vogler · screen adaptation','《作家之旅》（The Writer’s Journey，初版 1992）把神话母题整理为十二阶段，帮助写作与诊断。阶段可调换、压缩或省略，不能代替人物的具体选择。','The Writer’s Journey (first edition 1992) organizes mythic motifs into twelve stages for writing and diagnosis. Stages can be rearranged, compressed, or omitted; they do not replace particular choices.','哪个阶段帮你看清电影，哪个只让你填空？','Which stage clarifies the film, and which merely fills a box?',2)+`<a href="./hero-journey.html#vogler">${dual('十二阶段的完整课程 →','The complete twelve-stage lesson →')}</a>`+row('丹·哈蒙 · 故事圆环','Dan Harmon · Story Circle','八步把需求、陌生环境、代价与返回压缩成循环。它是现代叙事工作工具，不是《千面英雄》的原始八步，也不意味着所有人物都必须改善。','Eight steps compress need, unfamiliar conditions, cost, and return into a cycle. This is a modern working tool, not eight original steps from Campbell; change need not mean improvement.','代价真的改变了行为，还是只增加一场困难？','Does cost change behavior, or merely add a difficult scene?',2)+row('劳伦斯与朱厄特 · 美国单一神话','Lawrence & Jewett · American monomyth','这是一种文化批评：共同体受威胁、制度失灵，外来救世英雄通过特殊力量恢复秩序。它批判孤胆救世与反民主倾向，不只是给坎贝尔加上“现代”两个字。','This cultural critique examines a threatened community, failed institutions, and an exceptional outsider who restores order. It questions the lone savior and anti-democratic tendencies; it is not simply Campbell with modern added to the name.','谁负责日常修复？英雄走后，共同体有行动能力吗？','Who does everyday repair, and can the community act after the hero leaves?',3)+row('莫琳·默多克 · 女英雄之旅','Maureen Murdock · The Heroine’s Journey','1990 年的书回应男性中心模型，重视对“成功”的失落、下潜、关系修复与自我整合。其女性／男性词汇来自特定历史和心理框架，不应被当成生理性别规定。','The 1990 book responds to male-centered models through disillusionment with success, descent, relational healing, and integration. Its feminine/masculine vocabulary belongs to a situated psychological framework, not biological prescriptions.','故事奖励的是迎合现成成功，还是找到自己的完整性？','Does the story reward a received idea of success, or a person’s own wholeness?',2)+p('默多克的循环常写作：离开“女性性” → 认同“男性性” → 试炼 → 成功的幻觉 → 精神枯竭 → 下潜与启蒙 → 渴望重连“女性性” → 修复母女分裂 → 修复受伤的“男性性” → 整合。这些是其理论中的象征术语，不是要求女性遵守的十条生活准则。','Murdock’s cycle commonly describes separation from the feminine → identification with the masculine → trials → an illusory success → spiritual aridity → descent and initiation → longing to reconnect with the feminine → healing the mother/daughter split → healing the wounded masculine → integration. These are symbolic terms within her theory, not ten rules for women’s lives.')+evidence(['voglerBook','harmon','american','murdock']))+
section('story-circle','八步圆环：给短片的工作尺','Eight-step circle: a working measure for shorts',`<div class="wide-diagram">${art(2)}</div>`+circle.map((x,i)=>row((i+1)+' · '+x[0],x[1],x[2],x[3],'能否用一个动作或一次空间变化拍出来？','Can this be filmed as an action or spatial change?',i)).join('')+note('原创 90 秒练习','An original ninety-second exercise','一位剪辑师想赶上截止时间，借用陌生的自动工具，得到漂亮但失真的结果，付出丢失关键细节的代价，回到素材选择并保留不完美的真实。八步可以合并成三次选择；秒数是练习限制，不是哈蒙规定。','An editor facing a deadline tries an unfamiliar automated tool, gets a polished but distorted result, loses a crucial detail, then returns to the footage and chooses imperfect truth. Eight steps may compress into three choices. Ninety seconds is an exercise constraint, not Harmon’s rule.'))+
section('limits','何时不使用英雄模板？','When not to use a hero template?',row('《面孔》：关系不必被治愈','Faces: relations need not be healed','课程观察：情绪与权力不断移动，不能因为模型需要“归返”就把未解决的关系宣告为治愈。模型的空白也可以是有价值的发现。','Our reading: emotion and power keep shifting. An unresolved relationship should not be declared healed because a model demands return. The model’s gaps can themselves be useful findings.','电影拒绝解决的东西，是否正是它要你面对的？','Is what the film refuses to resolve exactly what it asks you to face?',3)+row('《利益区域》：观众的伦理位置','The Zone of Interest: the audience’s ethical position','课程观察：不要把施害者的日常当作等待救赎的英雄旅程。画外声与画内秩序的冲突，可能改变的是观众的感知责任，而不是给主角安排成长奖赏。','Our reading: do not recast perpetrators’ routines as a hero’s promised redemption. The conflict of offscreen sound and visible order may change the audience’s responsibility to perceive, rather than reward a protagonist’s growth.','谁被置于画外？谁的痛苦不能变成漂亮的结构道具？','Who is kept offscreen, and whose suffering must not become a neat structural device?',0)+`<a href="./films.html">${dual('去片单比较不同叙事伦理 →','Compare narrative ethics in the film studies →')}</a>`)+checklist([['先命名你正在用哪一位作者的哪一种模型，别统称“英雄之旅”。','Name the author and model being used instead of calling everything the hero’s journey.'],['给每个有帮助的对应，写一个不适用的反例。','For every useful mapping, write one counterexample.'],['为配角与共同体写独立的欲望，而不是只分配援助功能。','Give supporting people and communities independent desires, not only helper functions.'],['短片中把变化落实为动作；AI 影片中优先保持因果、空间与人物连续，而非只堆奇观。','In shorts, make change visible in action; in AI films, prioritize causal, spatial, and character continuity over accumulated spectacle.']])+quiz('这里为什么把 Modern Monomyth 做成比较专题？','Why is Modern Monomyth treated as a comparative topic here?',[['因为它唯一确定是一本由哈蒙写的书。','Because it uniquely identifies a book written by Harmon.'],['原书单无法唯一定位书目；因此明确解释范围，并区分写作工具与批评。','The list does not uniquely identify a book, so the scope is explicit and writing tools are distinguished from critiques.']],1,'这是公开的编辑解释，不是补造一个书名或作者。','This is an explicit editorial interpretation, not an invented bibliographic identification.')+refs(['voglerBook','vogler','harmon','wired','american','murdock']);}
function filmsPage(){return intro('看见选择，而不只辨认公式。','Study choices, not only formulas.','四个观摩入口：表演、阶级空间、广告节奏、画外伦理。','Four study routes: performance, class and space, advertising rhythm, and offscreen ethics.')+
p('事实与观察分开阅读：主创、年份与制作方法附来源；“导演观察”是本课程的分析建议，并非作者自述。','Read facts separately from analysis: credits, years, and production methods have sources; director observations are our study suggestions, not statements by the filmmakers.')+
section('faces','《面孔》 · 1968','Faces · 1968',p('导演／编剧：约翰·卡萨维茨（John Cassavetes）；摄影：Al Ruban。主演包括 John Marley、Lynn Carlin、Gena Rowlands、Seymour Cassel。Criterion 资料列为美国、黑白、16mm；BFI 的制作回顾提醒，不能把活生生的表演一概当作没有剧本的即兴。','Director/writer: John Cassavetes; cinematographer: Al Ruban. Cast includes John Marley, Lynn Carlin, Gena Rowlands, and Seymour Cassel. Criterion identifies the US black-and-white 16mm production; BFI’s production history cautions against treating its spontaneous-seeming performances as wholly unscripted improvisation.')+evidence(['faces','facesBFI'])+row('导演观察 · 表情不是结论','Director’s observation · expression is not a conclusion','观察近景、身体距离与情绪转换：笑声可以从亲密转向攻击，同一场戏里的权力不必稳定。长时间停留在关系中，比迅速给人物贴心理标签更有生产力。','Observe close framing, bodily distance, and emotional shifts: laughter can move from intimacy to attack, and power need not stay fixed within a scene. Remaining with a relationship may be more productive than quickly assigning a psychological label.','谁在努力维持气氛？谁被迫配合？','Who works to maintain the mood, and who must play along?',3)+p('结构连接：用《诗学》的“行动—后果”去追踪关系，而不是强行给每个人安排归返与治愈。与现代单一神话专题对读，允许不完成、失衡与矛盾。','Structural connection: trace action and consequence through the Poetics lesson without forcing return and healing on every person. Read beside Modern Monomyth and allow incompletion, imbalance, and contradiction.')+`<a href="./modern-monomyth.html#limits">${dual('模型的边界 →','The limits of a model →')}</a>`+checklist([['选两分钟，记录每次笑声前后谁拥有主动权。','Choose two minutes and record who has initiative before and after each laugh.'],['先排一版固定双人镜头，再排一版近景，比较观众被迫判断谁。','Stage a fixed two-shot and then close framing; compare whom the viewer is pushed to judge.'],['给演员可执行的关系任务，不要求机械复制“卡萨维茨式即兴”。','Give actors playable relational tasks instead of mechanically asking for Cassavetes-style improvisation.']]))+
section('pretty-woman','《风月俏佳人》 · 1990','Pretty Woman · 1990',p('导演：Garry Marshall；署名编剧：J. F. Lawton；摄影：Charles Minsky。Julia Roberts 饰 Vivian Ward，Richard Gere 饰 Edward Lewis。AFI 的剧情与片尾署名是本节事实依据。','Director: Garry Marshall; credited writer: J. F. Lawton; cinematographer: Charles Minsky. Julia Roberts plays Vivian Ward and Richard Gere plays Edward Lewis. AFI’s synopsis and screen credits ground the facts in this section.')+evidence(['pretty'])+row('导演观察 · 门槛、消费与选择','Director’s observation · thresholds, consumption, choice','从街道、酒店、商店到楼梯，观察谁能进入、谁规定规则、谁被观看。服装变化是可见信息，但不能代替分析薇薇安拒绝的权利与爱德华行为的改变。','Across street, hotel, shops, and fire escape, observe who may enter, who sets rules, and who is watched. Changing clothes provides visible information, but does not replace analysis of Vivian’s right to refuse and Edward’s changed actions.','镜头把她拍成被改造的对象，还是能决定的主体？','Does framing make her an object to transform, or a subject who can decide?',0)+p('结构连接：交易把两人放进共同世界；相处重写欲望；拒绝包养式安排让结尾选择获得意义。它可以与三幕和沃格勒的门槛功能比较，但不应简化为“富人拯救女人”的唯一解释。讨论也应包括性工作、阶级与童话式消费叙事的限制。','Structural connection: a transaction creates a shared world; proximity revises desire; refusal of a kept arrangement gives the ending’s choice significance. Compare three-act and Vogler threshold functions without reducing the film to one rich-man-saves-woman explanation. Include the limits of its framing of sex work, class, and consumer fairy tale.')+`<a href="./three-act.html#act-study">${dual('到三幕课程检查因果 →','Check causality in the three-act lesson →')}</a>`+checklist([['逐场记录谁付钱、谁设条件、谁可以拒绝。','Track who pays, sets conditions, and can refuse in each scene.'],['只看门口、走廊与高度差，画一张进入／排除的空间图。','Map access and exclusion using doorways, corridors, and differences in height.'],['将结尾与第一次交易对照：哪些动作重复，哪些关系反转？','Compare the ending with the first transaction: which actions repeat and which relations reverse?']]))+
section('bravia','Sony BRAVIA · 先校正主创','Sony BRAVIA · correct the credit first',note('Glazer 是《Paint》，不是《Balls》','Glazer directed Paint, not Balls','已核对：Jonathan Glazer 的 Sony BRAVIA 广告是《Paint》（2006），其制作公司 Academy Films 的作品页直接署名。著名的《Balls》（2005）由 Nicolai Fuglsig 执导，Lürzer’s Archive 记录其旧金山弹力球与主创。两支不可混署；这里不把未核实的其他品牌广告加到 Glazer 名下。','Verified: Jonathan Glazer directed Sony BRAVIA’s Paint (2006), directly credited by production company Academy Films. The famous Balls (2005) was directed by Nicolai Fuglsig; Lürzer’s Archive documents its San Francisco bouncing balls and credits. Do not conflate them. Other unverified brand spots are not attributed to Glazer here.')+evidence(['paint','paintYear','balls'])+row('导演观察 · 《Paint》的空间与节奏','Director’s observation · space and rhythm in Paint','把建筑几何、色彩事件与声画节奏分开记录，再看它们如何协调注意力。不要把品牌宣传的规模数字当作理解影像的前提；本页不复述未经确认的用漆量、爆破数量或唯一摄影方案。','Log architectural geometry, color events, and audiovisual rhythm separately, then study how they coordinate attention. Promotional scale figures are not a prerequisite for understanding an image; no unconfirmed paint quantities, explosion counts, or exclusive camera recipes are repeated here.','事件是按因果发展，还是按视觉与音乐的期待组织？','Do events develop causally, or through visual and musical anticipation?',1)+row('比较：《Balls》的运动方向','Compare movement in Balls','用作不同导演的对照片：追踪球体、坡道与人的尺度关系。它与《Paint》都服务色彩表达，但导演与具体视觉策略必须分开。','Use this as a comparison by a different director: follow the relation between balls, slopes, and human scale. Both ads foreground color, but authorship and visual strategies remain distinct.','如果把颜色拿掉，运动本身是否仍有句法？','If color were removed, would movement still have syntax?',2)+p('结构连接：广告不必完成英雄的内在成长。把救猫咪的“承诺兑现”当作观众期待的提问可以有用，但不能把 15 个节拍硬塞进每支短广告。','Structural connection: an ad need not complete a hero’s inner transformation. Save the Cat’s promise-of-the-premise can prompt a question about expectation, but fifteen beats should not be forced into every short advertisement.')+checklist([['画出三个方向不同、强度不同的视觉事件，不借用原广告画面。','Draw three original visual events with differing directions and intensities.'],['先剪无音乐版，再加声音，比较节奏是谁在主导。','Edit a silent version before adding sound, then compare what drives rhythm.'],['为你的 AI 短片设定可持续的空间与材料规则，避免只拼接奇观。','Give an AI short consistent spatial and material rules instead of splicing spectacles.']]))+
section('zone','《利益区域》 · 2023','The Zone of Interest · 2023',p('编剧／导演：Jonathan Glazer；摄影：Łukasz Żal；声音设计与混录等：Johnnie Burn；音乐：Mica Levi。主演 Sandra Hüller、Christian Friedel。英国文化协会列出 2023 年及戛纳首映；Leitz 对 Żal 的采访说明了固定、多机位与远程拍摄的工作方式。','Writer/director: Jonathan Glazer; cinematographer: Łukasz Żal; sound designer and re-recording mixer, among other sound roles: Johnnie Burn; composer: Mica Levi. Cast includes Sandra Hüller and Christian Friedel. British Council records 2023 and the Cannes premiere; Leitz’s interview with Żal explains the fixed, multicamera, remote approach.')+evidence(['zone','zoneCamera'])+note('观看提示','Viewing note','本片涉及奥斯维辛与纳粹施害者的日常。研究形式不应把受害者的痛苦转化成漂亮的摄影风格，也不能以冷静观察作为对暴行的中立。','The film concerns Auschwitz and the everyday lives of Nazi perpetrators. Studying form must not turn victims’ suffering into an attractive visual style or mistake detached observation for neutrality toward atrocities.')+row('导演观察 · 画内秩序，画外暴力','Director’s observation · visible order, offscreen violence','把画框当作信息与责任的边界：家居秩序与画外声音并置，让“没看见”不等于“不知道”。注意距离、重复与人物不回应声音的方式；不要把固定机位理解成没有立场。','Treat the frame as a boundary of information and responsibility: domestic order alongside offscreen sound makes not seeing different from not knowing. Observe distance, repetition, and the characters’ nonresponse to sound; a fixed camera is not a lack of position.','声音迫使你意识到哪些不在画框里的生命？','Whose lives does sound compel you to acknowledge beyond the frame?',0)+p('结构连接：与英雄旅程比较时，重点不是让施害者完成救赎弧，而是问观看者被置于何种伦理位置。与《诗学》的因果、构图课的“环境／主题”、以及画外空间一起讨论，会比机械分幕更有价值。','Structural connection: comparison with a hero journey should question the viewer’s ethical position rather than invent a redemptive arc for perpetrators. Causality from Poetics, environment/theme from composition, and offscreen space may be more productive than mechanical act division.')+`<a href="./composition.html">${dual('回到构图与意图 →','Return to composition and intention →')}</a>`+checklist([['绘制画内、画外两列声画清单，写清信息差。','Make paired on/offscreen image-and-sound lists and describe the information gap.'],['拍一段日常动作，用声音改变其伦理语境；不要模仿或消费真实暴行。','Film an everyday action and let sound change its ethical context; do not imitate or exploit real atrocities.'],['为每一个“不展示”写出理由与可能代价。','State a reason and possible cost for each decision not to show.']]))+
quiz('书单中的 Jonathan Glazer Sony BRAVIA 应如何标注？','How should the Jonathan Glazer Sony BRAVIA entry be labeled?',[['《Balls》（2005）是 Glazer。','Balls (2005) is by Glazer.'],['已确认 Glazer 执导《Paint》（2006）；《Balls》（2005）是 Nicolai Fuglsig。','Glazer is verified for Paint (2006); Balls (2005) is by Nicolai Fuglsig.']],1,'制作公司署名与广告档案分别支持这两项归属。','Production-company credits and the advertising archive distinguish the two attributions.')+refs(['faces','facesBFI','pretty','paint','paintYear','balls','zone','zoneCamera']);}
const bookEntries=[['index.html','救猫咪','Save the Cat!','Blake Snyder · 2005','从一句话梗概、十种故事类型到十五节拍与四十张卡片。','From logline and ten story types to fifteen beats and forty Board cards.'],['hero-journey.html','英雄之旅','The hero’s journey','Joseph Campbell · 1949 / 1990','区分《千面英雄》与谈话集，再读十七母题和沃格勒十二阶段。','Distinguish The Hero with a Thousand Faces from the conversation collection, then study seventeen motifs and Vogler’s twelve stages.'],['three-act.html','诗学与三幕结构','Poetics & three acts','Aristotle / Syd Field','古典的行动完整性不是现代三幕页数公式。','Classical completeness of action is not a modern act-page formula.'],['freytag.html','五部结构金字塔','Freytag’s pyramid','Gustav Freytag · 1863','五部分、三个转接时刻，以及居中的原始高潮。','Five parts, three transitional moments, and the original central climax.'],['modern-monomyth.html','现代单一神话','Modern monomyth','Vogler / Harmon / Lawrence & Jewett / Murdock','明确的编辑专题，不假造一本作者不明的书。','An explicitly editorial topic, not an invented book with an unidentified author.']];
function comparison(){const rows=[
[['开场画面','Opening Image'],['平凡世界','Ordinary World'],['出发前','Before departure'],['建立','Setup'],['引介','Introduction']],
[['主题呈现','Theme Stated'],['无固定对应','No fixed equivalent'],['出发前','Before departure'],['建立','Setup'],['引介中的价值线索','A value cue in introduction']],
[['铺垫','Set-Up'],['平凡世界','Ordinary World'],['出发前','Before departure'],['建立','Setup'],['引介','Introduction']],
[['催化剂','Catalyst'],['召唤','Call'],['出发','Departure'],['建立中的触发','A trigger in setup'],['可比较激发力','Compare exciting force']],
[['争辩／犹豫','Debate'],['拒绝召唤（可能）','Possible refusal'],['出发','Departure'],['建立','Setup'],['无固定对应','No fixed equivalent']],
[['进入第二幕','Break into Two'],['跨越门槛','Crossing threshold'],['出发→启蒙','Departure → initiation'],['转向对抗','Turn to confrontation'],['上升（功能近似）','Rise (functional approximation)']],
[['B 故事','B Story'],['盟友／导师（可能）','Possible allies / mentor'],['启蒙','Initiation'],['对抗','Confrontation'],['无固定对应','No fixed equivalent']],
[['游戏时间／类型承诺','Fun and Games'],['考验、盟友、敌人','Tests, allies, enemies'],['启蒙','Initiation'],['对抗','Confrontation'],['上升','Rise']],
[['中点','Midpoint'],['严峻考验／奖赏（可能）','Possible ordeal / reward'],['启蒙','Initiation'],['对抗中的转向','Turn within confrontation'],['中心顶点可比较，非同义','Central peak may be compared, not equated']],
[['坏人逼近','Bad Guys Close In'],['再考验／归途（可能）','Possible further tests / road back'],['启蒙／归返','Initiation / return'],['对抗','Confrontation'],['回落中的反作用','Counteraction in fall']],
[['一无所有','All Is Lost'],['无唯一对应','No unique equivalent'],['依故事而定','Story-dependent'],['对抗末段','Late confrontation'],['回落／危机（可能）','Possible fall / crisis']],
[['灵魂黑夜','Dark Night of the Soul'],['无唯一对应','No unique equivalent'],['依故事而定','Story-dependent'],['对抗末段','Late confrontation'],['无固定对应','No fixed equivalent']],
[['进入第三幕','Break into Three'],['走向最终考验','Toward a final test'],['归返（可能）','Possible return'],['转向解决','Turn to resolution'],['最后悬念（仅可能）','Last suspense (only possible)']],
[['结局／终场行动','Finale'],['复活／携灵药归返','Resurrection / return with elixir'],['归返（可能）','Possible return'],['解决','Resolution'],['结局；不等于中心高潮','Outcome, not the central climax']],
[['终场画面','Final Image'],['归返后的改变','Change after return'],['归返后','After return'],['解决后的状态','State after resolution'],['灾变／结局之后','After catastrophe / outcome']]];
return section('comparison','结构比较：功能近似，不是一一等号','Structure comparison: functions, not equivalences',p('这是本课程的比较表，不是任何作者给出的官方换算。列出的阶段可以缺席、重叠或顺序改变。特别注意：弗赖塔格原来的 Climax 居中，不能直接改成救猫咪的 Finale；坎贝尔十七母题也没有固定电影分钟数。','This is our teaching comparison, not an official conversion by any author. Stages can be absent, overlap, or change order. In particular, Freytag’s original Climax is central, not simply Save the Cat’s Finale; Campbell’s seventeen motifs also have no fixed cinematic timestamps.')+`<div class="table-wrap" tabindex="0" role="region" aria-label="结构比较，可横向滚动 / Structure comparison, horizontally scrollable"><table class="reference-table comparison-table"><thead><tr>${[['救猫咪节拍','Save the Cat beat'],['沃格勒 · 十二阶段','Vogler · twelve stages'],['坎贝尔 · 三阶段','Campbell · three phases'],['现代三幕功能','Modern act function'],['弗赖塔格 · 谨慎比较','Freytag · cautious comparison']].map(x=>`<th scope="col">${dual(...x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>`<${i?'td':'th'}${i?'':' scope="row"'}>${dual(...x)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`+evidence(['campbell','vogler','field','freytag']));}
const bookAuthors=[['布莱克·斯奈德 · 2005','Blake Snyder · 2005'],['约瑟夫·坎贝尔 · 1949 / 1990','Joseph Campbell · 1949 / 1990'],['亚里士多德 / 悉德·菲尔德','Aristotle / Syd Field'],['古斯塔夫·弗赖塔格 · 1863','Gustav Freytag · 1863'],['沃格勒 / 哈蒙 / 劳伦斯与朱厄特 / 默多克','Vogler / Harmon / Lawrence & Jewett / Murdock']];
function bookGrid(){
  return `<div class="books-grid">${bookEntries.map((x,i)=>`<article class="book-card${i===0?' is-selected':''}" data-book-index="${i}" tabindex="0" aria-expanded="${i===0?'true':'false'}" aria-controls="book-panel-${i}"><h3 class="book-card-title"><a href="./${x[0]}"><span class="zh" lang="zh-CN">${x[1]}</span><span class="en" lang="en">${x[2]}</span></a></h3><p class="book-card-byline">${dual(bookAuthors[i][0],bookAuthors[i][1])}</p><div class="book-card-copy">${p(x[4],x[5])}</div></article>`).join('')}${bookEntries.map((x,i)=>`<div class="book-card-panel" id="book-panel-${i}" data-panel="${i}" role="region"${i===0?'':' hidden'}>${art(i)}</div>`).join('')}</div>`;
}
function booksPage(){return intro('几种结构，几种看见电影的方法。','Different structures, different ways to see film.','一页一本书或一种模型；先读其问题，再决定是否采用。','One page per book or model; understand its question before choosing to use it.')+p('书单中的称呼并不都对应单一书籍：三幕结构是后来的实践模型；Modern Monomyth 在没有作者信息时是开放称呼。我们保留你的阅读路径，同时公开标注这些区别。','Not every name in the reading list identifies one book: three-act structure is a later working model, and Modern Monomyth remains an open label without an author. Your reading route is retained while these distinctions are made explicit.')+section('reading-list','书单与结构','Books & structures',bookGrid())+section('director-lessons','导演的视觉课程','Visual courses for directors',p('从想要的感受出发，再安排人物、空间与剪辑；所有新讲义内容直接可见。','Start with the intended feeling, then design people, space and editing; every new lesson remains visible.')+[['compositions.html','50 种实用构图','50 Compositions That Always Work'],['chemistry.html','电影化学反应','Cinematic Chemistry'],['composition-for-editing.html','为剪辑而构图','Composition for Editing']].map(x=>`<p><a href="./${x[0]}">${dual(x[1]+' →',x[2]+' →')}</a></p>`).join(''))+comparison()+section('watching-route','从阅读走向观看','From reading to watching',p('从《风月俏佳人》练习因果与门槛，从《面孔》看公式留下的空白，从 BRAVIA 的《Paint》分析短时视觉组织，再用《利益区域》讨论画外声与观看伦理。','Use Pretty Woman for causality and thresholds, Faces for the gaps left by formulas, BRAVIA’s Paint for short-form visual organization, and The Zone of Interest for offscreen sound and the ethics of looking.')+`<a href="./films.html">${dual('打开导演片单 →','Open the director’s viewing list →')}</a>`+p('电影史页把七份国家／地区思维导图整理为可展开的时代树；摄影与构图页把结构选择落实到镜头、空间、人物关系与声画。','Film History organizes seven country/region mind maps as expandable era trees; the image and composition lessons bring structural choices into lenses, space, relationships, and sound–image decisions.')+`<a href="./film-history.html">${dual('进入七国／地区电影史 →','Enter seven national / regional film histories →')}</a>`);}
const main=document.querySelector('#library-main'),volume=document.body.dataset.volume;const builders={books:booksPage,hero:heroPage,three:threePage,freytag:freytagPage,modern:modernPage,films:filmsPage};main.innerHTML=builders[volume]();
const sections=[...main.querySelectorAll('.cine-section[id]')];if(sections.length){const nav=document.createElement('nav');nav.className='cine-nav library-chapters';nav.setAttribute('aria-label','章节导航 / Chapter navigation');nav.innerHTML=sections.map(el=>`<a href="#${el.id}">${el.querySelector('h2').innerHTML}</a>`).join('');main.querySelector('.cine-intro').insertAdjacentElement('afterend',nav);if(volume==='books'){const links=[...nav.querySelectorAll('a')];const mark=id=>{links.forEach(a=>{const on=a.getAttribute('href')==='#'+id;a.classList.toggle('is-current',on);if(on)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')})};if(sections[0])mark(sections[0].id);if('IntersectionObserver' in window){const watch=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)mark(visible.target.id)},{rootMargin:'-18% 0px -55% 0px',threshold:[0.15,0.4]});sections.forEach(section=>watch.observe(section))}}}
if(volume==='books'){const grid=main.querySelector('.books-grid');if(grid){const cards=[...grid.querySelectorAll('.book-card')];const panels=[...grid.querySelectorAll('.book-card-panel')];let open=0;const cols=()=>{const template=getComputedStyle(grid).gridTemplateColumns;if(!template||template==='none')return 1;return template.split(' ').filter(Boolean).length};const place=()=>{const count=Math.max(1,cols());const rowEnd=Math.min(cards.length,Math.floor(open/count)*count+count)-1;const anchor=cards[rowEnd];const panel=panels[open];if(panel&&anchor&&panel.previousElementSibling!==anchor)anchor.after(panel)};const select=index=>{open=index;cards.forEach((card,i)=>{const on=i===index;card.classList.toggle('is-selected',on);card.setAttribute('aria-expanded',String(on))});panels.forEach((panel,i)=>{panel.hidden=i!==index});place()};cards.forEach((card,index)=>{card.addEventListener('click',event=>{if(event.target.closest('a'))return;select(index)});card.addEventListener('keydown',event=>{if(event.key!=='Enter'&&event.key!==' ')return;if(event.target.closest('a'))return;event.preventDefault();select(index)})});select(0);if(window.ResizeObserver){let frame=0;new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(place)}).observe(grid)}else window.addEventListener('resize',place,{passive:true})}}
function mode(value){if(!['bi','zh','en'].includes(value))value='bi';document.documentElement.dataset.mode=value;document.documentElement.lang=value==='en'?'en':'zh-CN';document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===value)));try{localStorage.setItem('film-learning-language',value)}catch(e){}}
mode(document.documentElement.dataset.mode);document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>mode(b.dataset.lang)));
main.addEventListener('click',ev=>{const b=ev.target.closest('[data-answer]');if(!b)return;const q=b.closest('.library-quiz'),ok=Number(b.dataset.answer)===Number(q.dataset.correct);q.querySelectorAll('[data-answer]').forEach(x=>{x.classList.remove('correct','incorrect');x.setAttribute('aria-pressed',String(x===b))});b.classList.add(ok?'correct':'incorrect');q.querySelector('.quiz-feedback').innerHTML=dual(ok?'答对了。':'再想想。',ok?'Correct.':'Try again.')+dual(q.querySelector('.quiz-feedback').dataset.zh,q.querySelector('.quiz-feedback').dataset.en)});
})();
